from collections import deque

def parse_tree(vals):
    if not vals or vals[0] == -1:
        return None

    class TreeNode:
        def __init__(self, val):
            self.val = val
            self.left = None
            self.right = None

    root = TreeNode(vals[0])
    queue = deque([root])
    i = 1
    while queue and i < len(vals):
        node = queue.popleft()
        # left child
        if i < len(vals):
            if vals[i] != -1:
                node.left = TreeNode(vals[i])
                queue.append(node.left)
            i += 1
        # right child
        if i < len(vals):
            if vals[i] != -1:
                node.right = TreeNode(vals[i])
                queue.append(node.right)
            i += 1
    return root

def level_order(root):
    if root is None:
        return []
    result = []
    queue = deque([root])
    while queue:
        level_size = len(queue)
        level = []
        for _ in range(level_size):
            node = queue.popleft()
            level.append(node.val)
            if node.left:
                queue.append(node.left)
            if node.right:
                queue.append(node.right)
        result.append(level)
    return result

line = input().strip()
if line == "" or line == "-1":
    vals = [-1]
else:
    vals = list(map(int, line.split()))

root = parse_tree(vals)
levels = level_order(root)
for level in levels:
    print(*level)

